function VisitProcess({settings:s}:{settings:Settings}) {
 const t=(key:string,fallback:string)=>s.content?.[key]??fallback;
 return <section id="how-it-works" className="process section" aria-labelledby="process-title">
  <h2 id="process-title">{t("copy_5cbb68967e","Как работает «Формула Элегантности»")}</h2>
  <ol className="process-steps">{visitSteps.map((original,index)=>{const step={...original,...s.visitSteps[index]};return <li className="process-step" key={step.number}>
   <span className="process-icon" aria-hidden="true"><VisitIcon kind={step.icon}/></span>
   <div className="process-copy"><span className="process-number" aria-hidden="true">{step.number}</span><h3>{step.title}</h3><p>{step.description}</p></div>
   {index<visitSteps.length-1&&<ArrowRight className="process-arrow" aria-hidden="true"/>}
  </li>;})}</ol>
 </section>;
}

function RoomPhoto({image,className=''}:{image:string;className?:string}){
 const [expanded,setExpanded]=useState(false);const alt=showroomCaption(image);
 useEffect(()=>{if(!expanded)return;const saved=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.body.style.overflow=saved;};},[expanded]);
 return <><button className={'room-photo '+className} aria-label={'Увеличить: '+alt} onClick={()=>setExpanded(true)}><Photo image={image} alt={alt}/><span className="room-photo-caption">{alt}<Plus size={18}/></span></button>{expanded&&<Dialog title={alt} onClose={()=>setExpanded(false)} wide><Photo image={image} alt={alt}/></Dialog>}</>;
}

